// Build one Slack message: traffic per competitor, highest first.
const rows = $input.all().map((i) => i.json).filter((d) => d.found !== false);
rows.sort((a, b) => (b.organicTraffic ?? 0) - (a.organicTraffic ?? 0));
const fmt = (n) => (n == null ? 'n/a' : Math.round(n).toLocaleString('en-US'));
const lines = rows.map((d, i) => `${i + 1}. *${d.domain}*: ${fmt(d.organicTraffic)} organic visits/month, ${fmt(d.organicKeywords)} keywords`);
const missing = $input.all().map((i) => i.json).filter((d) => d.found === false).map((d) => d.domain);
let text = `:bar_chart: *Weekly competitor organic traffic* (${rows[0]?.country ?? ''})\n` + lines.join('\n');
if (missing.length) text += `\n_No data: ${missing.join(', ')}_`;
return [{ json: { text } }];
